package com.hibernate.ecommerce.mapper;import com.hibernate.ecommerce.dto.ProductDTO;import com.hibernate.ecommerce.model.Product;public class ProductMapper {    public static ProductDTO toDTO(Product product){        if(product == null) return null;        return ProductDTO.builder()                .id(product.getId())                .name(product.getName())                .description(product.getDescription())                .price(product.getPrice())                .stock(product.getStock())                .build();    }    public static Product toEntity(ProductDTO dto){        if(dto == null) return null;        return Product.builder()                .id(dto.getId())                .description(dto.getDescription())                .name(dto.getName())                .price(dto.getPrice())                .stock(dto.getStock())                .build();    }}